import Foundation
import JavaScriptCore

/// Phase 1 JavaScript plugin runtime (JavaScriptCore).
///
/// What the bundled `plugin.js` actually is (verified by reading it, not
/// guessed): an ES module generated by `npm run build` from `src/`, whose
/// only export is `storeSync`. It expects a host object named `kino` with a
/// `fetch(url, options)` function, and it embeds the same catalog that is
/// in `plugin-catalog-seed.json`.
///
/// What this runtime does, honestly:
/// - Loads `kino-plugin.json` for id / version / apiVersion.
/// - Detects the exported function names from the source text.
/// - Provides a `kino` host object with `log` (real, bridged to Swift) and
///   `fetch` (stub: logs and returns null — network fetch for plugins is
///   NOT implemented in Phase 1).
/// - Strips the `export { storeSync };` line (JavaScriptCore does not
///   support ES-module syntax), evaluates the script, and if `storeSync`
///   is present calls `storeSync({})`. With an empty argument the plugin
///   takes its shipped-catalog path (`full(...)`) and does not need the
///   network, so the call is expected to resolve to the bundled catalog.
/// - Records the outcome in `status` / `diagnostics` instead of crashing
///   or pretending the full plugin API works.
///
/// Anything beyond this — plugin search, catalog fetching, playback
/// resolution, storage, screens — is Phase 2 work.
final class PluginRuntime: ObservableObject {
    @Published private(set) var status: String = "No cargado"
    @Published private(set) var exportedFunctions: [String] = []
    @Published private(set) var diagnostics: [String] = []
    @Published private(set) var pluginInfo: [String: String] = [:]

    private var context: JSContext?

    init() {
        load()
    }

    func load() {
        diagnostics = []
        loadPluginInfo()
        guard let url = Bundle.main.url(forResource: "plugin", withExtension: "js") else {
            status = "plugin.js no está en el bundle."
            return
        }
        guard let source = try? String(contentsOf: url, encoding: .utf8) else {
            status = "plugin.js no se pudo leer como UTF-8."
            return
        }
        exportedFunctions = detectExports(in: source)
        if exportedFunctions.isEmpty {
            status = "plugin.js cargado pero no se detectó ninguna función exportada."
            diagnostics.append("No se encontró 'export { ... }' en plugin.js.")
            return
        }

        let context = JSContext()
        context?.exceptionHandler = { [weak self] _, exception in
            self?.diagnostics.append("Error JS: \(exception?.toString() ?? "desconocido")")
        }
        self.context = context

        // Host object `kino`: log is real, fetch is a Phase 1 stub.
        let logBlock: @convention(block) (String) -> Void = { message in
            print("[kino plugin] \(message)")
        }
        context?.setObject(logBlock, forKeyedSubscript: "kinoLog" as NSString)
        context?.evaluateScript("""
            var kino = {
                log: function (message) { kinoLog(String(message)); },
                fetch: function (url, options) {
                    kinoLog("kino.fetch no implementado en Fase 1: " + String(url));
                    return null;
                }
            };
            """)

        // JavaScriptCore does not support ES-module `export` syntax.
        let evaluable = stripExports(from: source)
        context?.evaluateScript(evaluable)
        if let exception = context?.exception {
            diagnostics.append("Error al evaluar plugin.js: \(exception.toString())")
            status = "plugin.js no se pudo evaluar."
            return
        }

        guard let storeSync = context?.objectForKeyedSubscript("storeSync"),
              !storeSync.isUndefined else {
            status = "plugin.js evaluado, pero storeSync no está disponible en el contexto."
            diagnostics.append("storeSync está exportado en el archivo pero no quedó expuesto tras evaluar el script.")
            return
        }

        // storeSync({}) takes the shipped-catalog path and needs no network.
        let emptyArgument: [String: Any] = [:]
        let result = storeSync.call(withArguments: [emptyArgument])
        if let result {
            let text = result.toString() ?? ""
            diagnostics.append("storeSync({}) devolvió: \(text.prefix(300))")
            status = "Plugin cargado: storeSync presente y llamado con el catálogo incluido."
        } else {
            diagnostics.append("storeSync({}) no devolvió valor.")
            status = "Plugin cargado: storeSync presente, sin valor de retorno."
        }
    }

    private func loadPluginInfo() {
        guard let url = Bundle.main.url(forResource: "kino-plugin", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            diagnostics.append("kino-plugin.json no se pudo leer.")
            return
        }
        pluginInfo["id"] = json["id"] as? String ?? ""
        pluginInfo["name"] = json["name"] as? String ?? ""
        pluginInfo["version"] = json["version"] as? String ?? ""
        if let apiVersion = json["apiVersion"] {
            pluginInfo["apiVersion"] = "\(apiVersion)"
        }
        pluginInfo["author"] = json["author"] as? String ?? ""
    }

    /// Finds `export { name1, name2 };` in the source and returns the names.
    private func detectExports(in source: String) -> [String] {
        guard let start = source.range(of: "export {"),
              let end = source.range(of: "};", range: start.upperBound..<source.endIndex) else {
            return []
        }
        let body = source[start.upperBound..<end.lowerBound]
        return body
            .split(separator: ",")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    /// Removes the `export { ... };` statement so JavaScriptCore can
    /// evaluate the script. The exported functions stay defined globally.
    private func stripExports(from source: String) -> String {
        guard let start = source.range(of: "export {"),
              let end = source.range(of: "};", range: start.upperBound..<source.endIndex) else {
            return source
        }
        var copy = source
        copy.removeSubrange(start.lowerBound..<end.upperBound)
        return copy
    }
}
